def transform(grid):
    out = []
    base = grid[0][0]
    for br in range(3):
        row = []
        for bc in range(3):
            n = sum(grid[r][c] == 5 for r in range(br*4, br*4+3) for c in range(bc*4, bc*4+3))
            row.append(1 if n == 2 else base)
        out.append(row)
    return out
